function M.applyPalette(master,set)
 if bankMaster~=master then
  local byColor={};for i,color in ipairs(master)do byColor[color]=i-1 end
  bindings={}
  for _,entry in ipairs(M.bank)do
   local index=byColor[entry[1]]
   if index then bindings[#bindings+1]={index,entry[2]} end
  end
  bankMaster=master
 end
 for _,entry in ipairs(bindings)do set(entry[1],entry[2])end
end
